const items = $input.all();

function normalizeProductDetail(value) {
  if (typeof value !== 'string') {
    throw new Error('S007 未返回字符串字段 messageContent');
  }

  let text = value
    .trim()
    .replace(/\r\n?/g, '\n')
    .replace(/\\r\\n|\\r|\\n/g, '\n')
    .replace(/[ \t]*\n+[ \t]*/g, '\\n\\n');

  if (!text) {
    throw new Error('S007 返回的 messageContent 为空');
  }
  if (/[\r\n]/.test(text)) {
    throw new Error('messageContent 换行规范化失败：仍包含真实 CR/LF');
  }
  return text;
}

return items.map((item, index) => ({
  json: {
    ...item.json,
    messageContent: normalizeProductDetail(item.json?.messageContent),
  },
  ...(item.binary ? { binary: item.binary } : {}),
  pairedItem: item.pairedItem ?? { item: index },
}));

const items = $input.all();
const originalItems = $('Normalize Product Detail Newlines').all();
const HAN_RE = /\p{Script=Han}/u;
const MIXED_HAN_TOKEN_RE = /[\p{L}\p{M}\p{N}_-]*\p{Script=Han}+[\p{L}\p{M}\p{N}_-]*/gu;

function finalizeProductDetail(value) {
  if (typeof value !== 'string') {
    throw new Error('俄文详情修复结果 messageContent 不是字符串');
  }

  let text = value
    .trim()
    .replace(/\r\n?/g, '\n')
    .replace(/\\r\\n|\\r|\\n/g, '\n')
    .replace(/[ \t]*\n+[ \t]*/g, '\\n\\n');

  if (!text) {
    throw new Error('俄文详情修复结果 messageContent 为空');
  }

  if (HAN_RE.test(text)) {
    text = text
      .replace(MIXED_HAN_TOKEN_RE, '')
      .replace(/[ \t]{2,}/g, ' ')
      .replace(/[ \t]+([,.;:!?])/g, '$1')
      .replace(/([«([{])\s+/g, '$1')
      .replace(/\s+([»\])}])/g, '$1')
      .replace(/[ \t]*\\n\\n[ \t]*/g, '\\n\\n')
      .trim();
  }

  if (!text) {
    throw new Error('删除残留中文后 messageContent 为空');
  }
  if (HAN_RE.test(text)) {
    throw new Error('messageContent 中文字符清理失败');
  }
  if (/[\r\n]/.test(text)) {
    throw new Error('messageContent 换行规范化失败：仍包含真实 CR/LF');
  }
  return text;
}

return items.map((item, index) => {
  const pairedIndex = Number.isInteger(item.pairedItem?.item)
    ? item.pairedItem.item
    : index;
  const originalItem = originalItems[pairedIndex] ?? originalItems[index] ?? item;

  return {
    json: {
      ...originalItem.json,
      messageContent: finalizeProductDetail(item.json?.messageContent),
    },
    ...((item.binary || originalItem.binary)
      ? { binary: item.binary || originalItem.binary }
      : {}),
    pairedItem: item.pairedItem ?? originalItem.pairedItem ?? { item: pairedIndex },
  };
});
